{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "Human studies published in English were assessed for eligibility against the following criteria: Population: older children and adults who survived an episode of documented severe malnutrition in LMICs or famine exposure in childhood and adolescence (defined as 0-18 years of age). Exposure: exposure definitions included two closely related groups: (1) documented severe malnutrition in childhood ... or (2) famine conditions ... Outcomes: a range of cardiometabolic NCD outcomes ... was considered if they were based on an objective clinical outcome measured at least 1 year after exposure to severe malnutrition or famine. All study designs were eligible.",
      "reason": "Specifies population, exposure, eligible study designs (all designs), and follow-up timing for outcomes (objective clinical outcome measured at least 1 year after exposure). However, settings are not explicitly specified, and there is no explicit statement of all question-framework components (e.g., follow-up requirements beyond the 1-year outcome timing)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "Human studies published in English were assessed for eligibility against the following criteria: ... Grey literature and unpublished studies were excluded.",
      "reason": "Language (English) and publication/report status exclusion (grey literature and unpublished studies) are stated. Dissemination year is not specified in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided that the review distinguishes exclusions due to (i) outcomes not measured versus (ii) outcome results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "Data from studies of famine survivors and documented severe childhood malnutrition were analysed separately to account for the different nature of the exposures.",
      "reason": "The review specifies groups used for analysis/synthesis at least at the exposure level (famine survivors vs documented severe childhood malnutrition). However, the retrieved evidence does not show how these groups are explicitly linked to the specific comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "Although severe stunting is a form of severe malnutrition, we excluded studies that considered stunted children alone as the association between stunting and increased NCD risk has been described elsewhere.",
      "reason": "A rationale is provided for a notable eligibility restriction (excluding studies of stunted children alone). Other notable restrictions mentioned (e.g., exclusion of grey literature/unpublished studies) do not include rationales in the retrieved evidence."
    }
  ],
  "confidence": 74
}

